/* Shared archive experience. Live records are stored by the authenticated API. */
const archiveDemoId=()=>crypto.randomUUID?.()||('demo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));
let archiveItems=[],archiveError='',archiveTab='all',archiveQuery='',archiveYear=new Date().getFullYear(),archiveMap=null,archiveGroupTimer=null,archiveRecorder=null,archiveStream=null,archiveDemo=null;
const archiveKinds={story:['Sesli hikâyeler','mic'],recipe:['Aile tarifleri','utensils'],question:['Aileye sor','circle-help'],memory:['Fotoğrafın hikâyesi','images'],memorial:['Anma sayfaları','flower-2'],achievement:['Başarılarımız','award'],source:['Bilginin kaynağı','scroll-text'],migration:['Göç yolculuğu','route'],capsule:['Zaman kapsülleri','lock-keyhole'],exhibition:['Dijital sergiler','gallery-horizontal'],poll:['Buluşma planları','calendar-check'],directory:['Aile rehberi','contact'],quiz:['Aile yarışmaları','trophy']};
function archivePeopleOptions(){return[['','Kişi seçmeden devam et'],...state.people.map(p=>[p.id,p.name])];}
function archivePhotoOptions(){return[['','Fotoğraf seçmeden devam et'],...state.photos.map(p=>[p.id,p.title])];}
const aButton=(label,action,id='',cls='')=>button(label,'ar-'+action,null,cls,'type="button" '+(id?'data-id="'+esc(id)+'"':''));
function archiveDemoSave(){try{localStorage.setItem('sf-archive-preview-v1',JSON.stringify(archiveDemo));}catch{}}
async function archiveApi(path,method='GET',b){if(!demoMode)return api('/api/archive'+path,method,b);
 if(!archiveDemo){try{archiveDemo=JSON.parse(localStorage.getItem('sf-archive-preview-v1'));}catch{}if(!archiveDemo){const p=state.people[0],ph=state.photos[0],time=new Date().toISOString();archiveDemo={entries:[{id:'sample-story',kind:'story',title:'Bir bayram sabahını hatırlamak',body:'Bu kayıt örnektir. Büyüklerimizin anlatılarını, fotoğraflarını ve sesini aynı yerde koruyabileceğimiz bir sayfa.',personId:p?.id,photoId:ph?.id,data:{date:'1985-06-19'},status:'approved',visibility:'family',createdBy:state.user.id,author:'Örnek aile arşivi',createdAt:time,updatedAt:time,media:[]},{id:'sample-achievement',kind:'achievement',title:'Yeni bir başlangıç',body:'Örnek kutlama kaydı. Mezuniyetlerimizi ve hayatımızdaki güzel gelişmeleri burada paylaşabiliriz.',personId:p?.id,data:{date:time.slice(0,10)},status:'approved',visibility:'family',createdBy:state.user.id,author:'Örnek aile arşivi',createdAt:time,updatedAt:time,media:[]}],comments:[],groups:[],messages:[],votes:[]};}}
 const d=archiveDemo,can=e=>!e.deletedAt&&(e.visibility!=='private'||e.createdBy===state.user.id)&&(e.status==='approved'||e.createdBy===state.user.id||isStaff());let result={ok:true};
 if(path==='/entries'&&method==='GET')return{items:d.entries.filter(can).map(e=>e.opensAt&&e.opensAt>new Date().toISOString()?{...e,body:'',data:{},media:[],locked:true}:e)};
 if(path==='/entries'&&method==='POST'){const e={...b,id:archiveDemoId(),createdBy:state.user.id,author:state.user.name,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),status:isStaff()||b.visibility==='private'?'approved':'pending',media:[]};d.entries.unshift(e);result={id:e.id};}
 const m=path.match(/^\/entries\/([^/]+)(?:\/(comments|vote|media|seal|finalize))?$/);if(m){const e=d.entries.find(x=>x.id===m[1]&&can(x));if(!e)throw Error('Kayıt bulunamadı.');if(!m[2]){if(method==='GET')return e;if(method==='DELETE')e.deletedAt=new Date().toISOString();if(method==='PATCH'){if(b.verify)e.data.verified=true;else Object.assign(e,b);}}
 if(m[2]==='comments'){if(method==='GET')return{items:d.comments.filter(c=>c.entryId===e.id)};d.comments.push({id:archiveDemoId(),entryId:e.id,body:b.body,author:state.user.name,status:isStaff()?'approved':'pending',createdAt:new Date().toISOString()});}
 if(m[2]==='vote'){if(method==='GET')return{items:d.votes.filter(v=>v.entryId===e.id)};const value=e.kind==='quiz'?JSON.stringify({score:e.data.questions.reduce((n,q,i)=>n+(q.answer===b.answers[i]),0),total:e.data.questions.length}):b.value;d.votes=d.votes.filter(v=>v.entryId!==e.id||v.userId!==state.user.id);d.votes.push({entryId:e.id,userId:state.user.id,name:state.user.name,value});result={value};}
 if(m[2]==='seal')e.sealed=true;if(m[2]==='finalize'){const ev=await api('/api/events','POST',{title:e.title,type:'gathering',date:b.date,place:e.data.place,description:e.body});e.eventId=ev.id;result={id:ev.id};}if(m[2]==='media')throw Error('Ses ve video dosyaları canlı sitede hesabınla yüklenebilir. Metin kaydın saklandı.');}
 if(path.startsWith('/comments/')){const c=d.comments.find(x=>x.id===path.split('/')[2]);if(c)Object.assign(c,b);}
 if(path==='/groups'){if(method==='GET')return{items:d.groups};const g={...b,id:archiveDemoId(),createdBy:state.user.id};d.groups.push(g);result={id:g.id};}
 const gm=path.match(/^\/groups\/([^/]+)(?:\/(messages|members))?$/);if(gm){const g=d.groups.find(x=>x.id===gm[1]);if(method==='GET')return{group:g,members:[state.user],items:d.messages.filter(x=>x.groupId===g.id).reverse()};if(gm[2]==='messages')d.messages.push({id:Date.now(),groupId:g.id,body:b.body,name:state.user.name,userId:state.user.id});}
 if(['/transfer','/guardians','/photo-settings','/merges'].some(p=>path.startsWith(p)))throw Error('Bu yönetim işlemi canlı sitede kullanılabilir.');archiveDemoSave();return result;
}
async function archiveLoad(){archiveError='';try{let path='/entries',items=[],more=true;while(more){const r=await archiveApi(path);items.push(...r.items);more=r.hasMore;path='/entries?offset='+r.nextOffset;}archiveItems=items;}catch(e){archiveError=e.message;}}
function archiveCard(e){const photo=state.photos.find(p=>p.id===e.photoId)||(e.kind==='exhibition'?state.photos.find(p=>p.id===e.data.photoIds?.[0]):null);return`<article class="ar-card">${photo&&!e.locked?`<img loading="lazy" src="${esc(photo.url)}" alt="${esc(photo.title)}">`:''}<div class="ar-card-body"><div class="ar-meta">${icon(archiveKinds[e.kind]?.[1]||'book-open')}<span>${archiveKinds[e.kind]?.[0]||'Arşiv'}</span>${e.status!=='approved'?`<span class="pill">${e.status==='pending'?'Onay bekliyor':'Reddedildi'}</span>`:''}${e.visibility==='private'?'<span class="pill">Özel</span>':''}</div><h3>${esc(e.title)}</h3><p>${esc(e.locked?'Açılacağı tarih: '+new Date(e.opensAt).toLocaleDateString('tr-TR'):e.body.slice(0,180))}</p><div class="ar-card-foot"><small>${esc(e.author||state.people.find(p=>p.id===e.personId)?.name||'Aile arşivi')}</small>${aButton(e.locked?'Kapsülü gör':'Aç','open',e.id,'small')}</div></div></article>`;}
function archiveSearchTerms(value){return value.toLocaleLowerCase('tr').replace(/(\d{3})0[’']?lar[\p{L}]*/gu,'$1').replace(/[’']/g,' ').replace(/fotoğraflar[\p{L}]*|fotoğraf|anıların|anıları|yılında|yıllarında|bana|göster|bul|olan|için/gu,' ').split(/\s+/).map(w=>w.replace(/(?:daki|deki|teki|taki)$/,'')).filter(w=>w.length>1&&!['da','de','ta','te','ve'].includes(w));}
function archiveSearchMatch(e){const s=(e.title+' '+e.body+' '+JSON.stringify(e.data)+' '+(state.people.find(p=>p.id===e.personId)?.name||'')+' '+(state.photos.find(p=>p.id===e.photoId)?.place||'')).toLocaleLowerCase('tr');return archiveSearchTerms(archiveQuery).every(w=>s.includes(w));}
function archivePage(){const list=archiveItems.filter(e=>(archiveTab==='all'||e.kind===archiveTab)&&archiveSearchMatch(e));return heading('GELECEĞE BIRAKTIKLARIMIZ','Yaşayan Arşiv','Hikâyeleri dinle, bir soruyu yanıtla, yeni bir hatıra bırak.',aButton('Arşive katkı ekle','new','','primary')+aButton('Aile kitabını hazırla','book'))+`<div class="ar-toolbar"><label class="search">${icon('search')}<input id="ar-search" aria-label="Arşivde ara" placeholder="Örneğin 1980, Gaziantep, düğün…" value="${esc(archiveQuery)}"></label>${aButton('Kolay görünüm','simple')}</div><div class="ar-filters" role="group" aria-label="Arşiv türleri">${[['all',['Tümü','library']],...Object.entries(archiveKinds)].map(([k,v])=>`<button class="ar-filter ${archiveTab===k?'active':''}" data-action="ar-tab" data-id="${k}">${icon(v[1])}${v[0]}</button>`).join('')}</div>${archiveError?`<div role="alert" class="notice">${esc(archiveError)} ${aButton('Yeniden dene','reload')}</div>`:''}${archiveTab==='directory'?`<div class="notice">Yalnızca rehberde görünmeyi kabul eden üyeler burada yer alır. Şehir adıyla arayıp bir buluşma için mesaj gönderebilirsin.</div>`:''}<div class="ar-grid">${list.map(archiveCard).join('')}</div>${!list.length?empty('Burada yeni bir hikâye başlayabilir.','Bu bölümde henüz görünür kayıt yok.','ar-new','İlk katkıyı ekle'):''}`;}
function connectionsPage(){return heading('HER BAĞIN BİR HİKÂYESİ VAR','Aile Bağlarımız','Akrabalık yollarını ve ailemizin yıllar içindeki değişimini keşfet.')+`<div class="ar-tools"><section class="card"><span class="eyebrow">NEYİMİZ OLUYOR?</span><h2>Aramızdaki bağ</h2><form id="ar-kin-form" class="stack">${select('Birinci kişi','kinA',archivePeopleOptions(),personId)}${select('İkinci kişi','kinB',archivePeopleOptions())}<button class="btn primary" type="submit">${icon('route')}Bağlantıyı göster</button></form><div id="ar-kin-result" aria-live="polite"></div></section><section class="card ar-year-card"><span class="eyebrow">O TARİHTE AİLEMİZ</span><h2 id="ar-year-label">${archiveYear}</h2><label for="ar-year">Yıl seç</label><input id="ar-year" type="range" min="${Math.min(1900,...state.people.filter(p=>p.birthDate).map(p=>Number(p.birthDate.slice(0,4))))}" max="${new Date().getFullYear()}" value="${archiveYear}"><div id="ar-year-result"></div></section></div><section class="card ar-section"><div class="section-head"><h2>Ailemizin göç yolculuğu</h2>${aButton('Bir yolculuk ekle','new-kind','migration')}</div><div id="ar-migration-map" aria-label="Aile göç güzergâhları"></div><div id="ar-migrations"></div></section>${isStaff()?`<section class="card ar-section"><h2>Tek kişi, doğru kayıt</h2><p>Yinelenen kişileri incele, bağlantılarını birleştir. Sonraki değişiklikler güvenli geri almayı engelleyebilir.</p>${aButton('Birleştirme araçları','merges')}</section>`:''}`;}
function kinshipPath(people,relations,a,b){if(a===b)return[{id:a,label:'Aynı kişi'}];const ids=new Set(people.map(p=>p.id)),adj=new Map();for(const p of people)adj.set(p.id,[]);for(const r of relations){if(!ids.has(r.personA)||!ids.has(r.personB))continue;adj.get(r.personA).push({id:r.personB,label:r.type==='spouse'?'eşi':r.type==='adoptive'?'evlatlık bağıyla çocuğu':'çocuğu'});adj.get(r.personB).push({id:r.personA,label:r.type==='spouse'?'eşi':r.type==='adoptive'?'evlatlık bağıyla ebeveyni':'ebeveyni'});}const queue=[[{id:a,label:'Başlangıç'}]],seen=new Set([a]);for(let i=0;i<queue.length;i++){const path=queue[i];for(const n of adj.get(path.at(-1).id)||[]){if(seen.has(n.id))continue;const next=[...path,n];if(n.id===b)return next;seen.add(n.id);queue.push(next);}}return[];}
function kinshipLabel(path){const steps=path.slice(1).map(x=>x.label);if(steps.length===1)return steps[0];if(steps.join(',')==='ebeveyni,çocuğu')return'kardeşi';if(steps.join(',')==='ebeveyni,ebeveyni')return'büyük ebeveyni';if(steps.join(',')==='çocuğu,çocuğu')return'torunu';if(steps.join(',')==='ebeveyni,ebeveyni,çocuğu,çocuğu')return'kuzeni';return'Bağlantı yolu aşağıda gösteriliyor';}
function drawArchiveYear(){const y=archiveYear,cut=y+'-12-31',living=state.people.filter(p=>p.birthDate&&p.birthDate<=cut&&(!p.deathDate||p.deathDate>cut)),unknown=state.people.filter(p=>!p.birthDate).length;const moments=[...state.people.flatMap(p=>[['Doğum',p.birthDate],['Vefat',p.deathDate]].filter(([,d])=>d?.startsWith(String(y))).map(([kind,date])=>({title:p.name+' · '+kind,date,action:'profile',id:p.id}))),...state.events.filter(e=>e.date?.startsWith(String(y))).map(e=>({title:e.title,date:e.date,action:'event-detail',id:e.id})),...archiveItems.filter(e=>!e.locked&&(e.data.date?.startsWith(String(y))||e.data.year===y)).map(e=>({title:e.title,date:e.data.date||String(y),action:'ar-open',id:e.id}))].sort((a,b)=>a.date.localeCompare(b.date));$('#ar-year-label').textContent=y;$('#ar-year-result').innerHTML=`<p><strong>${living.length}</strong> kişi yıl sonunda hayatta görünüyor.</p><small>${unknown} kişinin doğum tarihi bilinmediği için sayıma alınmadı. Vefat tarihi boş kayıtlar hayatta kabul edilir.</small><div class="ar-year-people">${living.map(p=>`<button data-action="profile" data-id="${esc(p.id)}">${avatar(p)}<span>${esc(p.name)}<small>${y-Number(p.birthDate.slice(0,4))} yaş · 31 Aralık</small></span></button>`).join('')}</div><h3>O yılın dönüm noktaları</h3>${moments.map(e=>`<article class="ar-comment"><small>${esc(e.date)}</small><br><button type="button" class="btn small" data-action="${e.action}" data-id="${esc(e.id)}">${esc(e.title)}</button></article>`).join('')||'<p>Bu yıla ait kayıt yok.</p>'}`;}
function drawMigrationMap(){if(!window.L||!window.FamilyWorld)return;archiveMap=L.map('ar-migration-map',{minZoom:2,maxZoom:10}).setView([36,28],3);L.geoJSON(window.FamilyWorld,{style:{color:'#fff',weight:1,fillColor:'#a9b797',fillOpacity:1}}).addTo(archiveMap);archiveMap.attributionControl.addAttribution('Natural Earth');const entries=archiveItems.filter(e=>e.kind==='migration'&&e.status==='approved');for(const e of entries){const d=e.data,pts=[[d.fromLat,d.fromLng],[d.toLat,d.toLng]],label=document.createElement('span');label.textContent=e.title+' · '+d.year;L.polyline(pts,{color:'#846331',weight:3,dashArray:'7 7'}).bindPopup(label).addTo(archiveMap);pts.forEach(p=>L.circleMarker(p,{radius:6,color:'#263e33'}).addTo(archiveMap));}$('#ar-migrations').innerHTML=entries.sort((a,b)=>a.data.year-b.data.year).map(e=>`<button class="ar-migration-row" data-action="ar-open" data-id="${esc(e.id)}"><strong>${e.data.year}</strong><span>${esc(e.data.from)} → ${esc(e.data.to)}</span><small>${esc(e.title)}</small></button>`).join('')||'<p>İlk göç kaydını ekleyerek aile yolculuğunu başlat.</p>';}
function groupsPage(){return heading('AİLE İÇİNDE BİR HALKA DAHA','Aile Grupları','Kuzenlerle, aile kolunla veya aynı şehirdeki yakınlarınla konuş.',aButton('Grup oluştur','group-new','','primary'))+'<div id="ar-groups" class="ar-grid" aria-live="polite">Gruplar yükleniyor…</div>';}
