 let e=seed.id?seed:null,d=seed.data||{},extra='';const documents=['source','question'].includes(kind)?(await familyApi('/api/documents')).items:[];
 if(['story','memory','memorial','achievement'].includes(kind))extra+=input('Tarih (biliniyorsa)','date',d.date,'date');
 if(kind==='recipe')extra+=input('Kaç kişilik?','servings',d.servings)+area('Malzemeler','ingredients',d.ingredients,'required')+area('Hazırlanışı','steps',d.steps,'required');
 if(['source','question'].includes(kind))extra+=input('Hangi bilgi / hangi soru?','claim',d.claim)+input('Anlatan kişi veya kaynak adı','narrator',d.narrator)+area('Kanıt veya kaynak ayrıntısı','evidence',d.evidence)+select('Bilginin niteliği','confidence',[['uncertain','Henüz kesin değil'],['oral','Aileden aktarılan anlatı'],['documented','Belgeye dayanıyor']],d.confidence)+select('Aile Sandığı’ndan kaynak belge','documentId',[['','Belge seçmeden devam et'],...documents.map(x=>[x.id,x.title])],d.documentId);
 if(kind==='migration')extra+=`<div class="field full"><p>Önce çıkış, sonra varış noktasını haritaya dokunarak seç. İstersen noktaları tekrar seçebilirsin.</p><div class="row"><label><input type="radio" name="mapTarget" value="from" checked> Çıkış noktası</label><label><input type="radio" name="mapTarget" value="to"> Varış noktası</label></div><div id="ar-route-picker"></div><p id="ar-route-pick-status" role="status">İki noktayı seç.</p></div>`+input('Göç yılı','year',d.year||new Date().getFullYear(),'number','required min="1" max="'+new Date().getFullYear()+'"')+input('Çıkış yeri','from',d.from,'text','required')+input('Varış yeri','to',d.to,'text','required')+input('Çıkış enlemi','fromLat',d.fromLat,'hidden','required step="any" min="-85" max="85"')+input('Çıkış boylamı','fromLng',d.fromLng,'hidden','required step="any" min="-180" max="180"')+input('Varış enlemi','toLat',d.toLat,'hidden','required step="any" min="-85" max="85"')+input('Varış boylamı','toLng',d.toLng,'hidden','required step="any" min="-180" max="180"');
 if(kind==='capsule')extra+=input('Ne zaman açılsın?','opensAt',seed.opensAt?.slice(0,16),'datetime-local','required')+'<div class="field full"><label for="ar-capsule-file">Ses veya video (isteğe bağlı, en fazla 16 MB)</label><input id="ar-capsule-file" type="file" accept="audio/*,video/mp4,video/webm"></div><div class="notice full">Kapsül kaydedildiğinde mühürlenir. Açılış tarihine kadar içeriği sahibine de gösterilmez.</div>';
 if(kind==='poll')extra+=area('Tarih seçenekleri (her satıra YYYY-AA-GG)','options',d.options?.join('\n'),'required placeholder="2026-12-20\n2026-12-27"')+input('Buluşma yeri','place',d.place);
 if(kind==='directory')extra+=input('Şehir','city',d.city)+input('Meslek / uzmanlık','profession',d.profession)+area('Hangi konularda yardımcı olabilirsin?','help',d.help)+'<label class="tag-check full"><input type="checkbox" name="consent" required> Bu bilgilerin aile rehberinde görünmesini istiyorum.</label>';
 if(kind==='exhibition')extra+=`<div class="field full"><label>Sergi fotoğrafları · En fazla 40</label><div class="ar-photo-picker">${state.photos.filter(p=>p.status==='approved').map(p=>`<label><input type="checkbox" name="photoIds" value="${esc(p.id)}" ${d.photoIds?.includes(p.id)?'checked':''}><img src="${esc(p.url)}" alt=""><span>${esc(p.title)}</span></label>`).join('')||'<p>Önce Avlu’ya fotoğraf ekle.</p>'}</div></div>`;
 if(kind==='quiz')extra+=`<div class="field full"><label>Sorular</label><p>Her satır: Soru | Seçenek 1 | Seçenek 2 | Doğru seçenek numarası</p><textarea name="questions" required rows="6" placeholder="Ailemizin buluşma noktası? | Aile Konağı | Başka bir yer | 1">${esc((d.questions||[]).map(q=>[q.question,...q.options,q.answer+1].join(' | ')).join('\n'))}</textarea>${aButton('Aile kayıtlarından soru hazırla','quiz-generate')}</div>`;
