 modal(esc(e.title),`<div class="ar-detail">${p&&!locked?`<img class="image-view" src="${esc(p.url)}" alt="${esc(p.title)}">`:''}<span class="eyebrow">${archiveKinds[e.kind]?.[0]}</span>${locked?`<div class="ar-sealed">${icon('lock-keyhole')}<h3>Gelecekte buluşacağız.</h3><p>${new Date(e.opensAt).toLocaleString('tr-TR')} tarihinde açılacak.</p></div>`:`<p class="ar-prose">${esc(e.body)}</p>${e.personId?aButton(esc(state.people.find(p=>p.id===e.personId)?.name||'Kişi profili'),'person',e.personId):''}${extra}<section class="ar-section"><h3>Birlikte hatırladıklarımız</h3><div id="ar-comments">Yükleniyor…</div><form id="ar-comment-form" class="stack">${area('Hatıran veya cevabın','body','','required maxlength="5000"')}<button type="submit" class="btn">Katkımı ekle</button><div class="form-error"></div></form></section>`}<div class="form-actions">${isStaff()&&e.status==='pending'?aButton('Onayla','approve',e.id)+aButton('Reddet','reject',e.id):''}${canEdit&&!locked?aButton('Düzenle','edit',e.id):''}${canEdit?aButton('Kaldır','delete',e.id,'danger'):''}</div></div>`,true);
