async function archiveFormTask(f,fn){const b=$('[type=submit]',f);if(b)b.disabled=true;try{await fn(f);}catch(e){const el=$('.form-error',f);if(el)el.textContent=e.message;else toast(e.message);}finally{if(b)b.disabled=false;}}
async function archiveUploadMedia(id,file){if(!file)return;if(file.size>16*1024*1024)throw Error('Dosya 16 MB’tan büyük. Daha kısa bir kayıt seç.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Dosya okunamadı.'));r.readAsDataURL(file);});await archiveApi('/entries/'+id+'/media','POST',{data,mime:file.type});await archiveLoad();await archiveOpen(id);toast('Ses / video arşive eklendi.');}
function stopArchiveRecording(){if(archiveRecorder?.state==='recording')archiveRecorder.stop();archiveStream?.getTracks().forEach(t=>t.stop());archiveStream=null;}
async function archiveRecord(id){if(archiveRecorder?.state==='recording'){stopArchiveRecording();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Bu tarayıcıda ses kaydı desteklenmiyor. Dosya seçerek yükleyebilirsin.');archiveStream=await navigator.mediaDevices.getUserMedia({audio:true});archiveRecorder=new MediaRecorder(archiveStream);let chunks=[],size=0;const mime=archiveRecorder.mimeType;archiveRecorder.ondataavailable=e=>{chunks.push(e.data);size+=e.data.size;if(size>=15*1024*1024)stopArchiveRecording();};archiveRecorder.onstop=()=>{archiveStream?.getTracks().forEach(t=>t.stop());archiveStream=null;archiveUploadMedia(id,new Blob(chunks,{type:mime})).catch(e=>toast(e.message));};archiveRecorder.start(1000);$('#ar-record-state').textContent='Kayıt sürüyor. Bitirmek için aynı düğmeye bas.';}
function archiveExhibit(e){const photos=(e.data.photoIds||[]).map(id=>state.photos.find(p=>p.id===id)).filter(Boolean);if(!photos.length)throw Error('Sergide görebileceğin fotoğraf yok.');let index=0;function draw(){const p=photos[index];modal(esc(e.title),`<div class="ar-exhibit"><img src="${esc(p.url)}" alt="${esc(p.title)}"><div><p>${esc(e.body)}</p>${(e.media||[]).filter(m=>m.mime.startsWith('audio/')).map(m=>`<audio controls src="/archive-media/${esc(m.id)}"></audio>`).join('')}<span>${index+1} / ${photos.length}</span><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="row"><button class="btn" id="ar-slide-prev" ${!index?'disabled':''}>Önceki</button><button class="btn" id="ar-slide-next" ${index===photos.length-1?'disabled':''}>Sonraki</button></div></div></div>`,true);$('#ar-slide-prev').onclick=()=>{index--;draw();};$('#ar-slide-next').onclick=()=>{index++;draw();};}draw();}
async function archiveGroupNew(){const members=demoMode?[]:(await api('/api/community')).members;modal('Yeni aile grubu',form(input('Grup adı','name','','text','required minlength="2"')+area('Grup açıklaması','description')+`<div class="field full"><label>Katılacak aile üyeleri</label><div class="tags-picker">${members.map(m=>`<label class="tag-check"><input name="members" type="checkbox" value="${esc(m.id)}">${esc(m.name)}</label>`).join('')}</div></div>`));submitWith(async(b,f)=>{await archiveApi('/groups','POST',{...b,members:new FormData(f).getAll('members')});closeModal();go('groups');await archiveBindGroups();});}
