async function archiveGroupOpen(id){const r=await archiveApi('/groups/'+id);modal(esc(r.group.name),`<p>${r.members.map(x=>esc(x.name)).join(', ')}</p><div id="ar-group-log" class="ar-group-log" role="log"></div><form id="ar-group-form" class="stack">${area('Mesajın','body','','required maxlength="4000"')}<button class="btn primary" type="submit">Gönder</button><div class="form-error"></div></form><div class="form-actions">${r.group.createdBy===state.user.id?aButton('Üye ekle','group-add',id):aButton('Gruptan ayrıl','group-leave',id)}</div>`,true);function draw(data){const el=$('#ar-group-log');if(!el)return;el.innerHTML=[...data.items].reverse().map(m=>`<div class="ar-comment"><strong>${esc(m.name)}</strong><p>${esc(m.body)}</p></div>`).join('')||'<p>İlk selamı sen ver.</p>';el.scrollTop=el.scrollHeight;}draw(r);$('#ar-group-form').onsubmit=async ev=>{ev.preventDefault();await archiveFormTask(ev.currentTarget,async f=>{await archiveApi('/groups/'+id+'/messages','POST',{body:new FormData(f).get('body')});f.reset();draw(await archiveApi('/groups/'+id));});};clearInterval(archiveGroupTimer);archiveGroupTimer=setInterval(async()=>{if(!$('#ar-group-log')){clearInterval(archiveGroupTimer);return;}try{draw(await archiveApi('/groups/'+id));}catch(e){toast(e.message);clearInterval(archiveGroupTimer);}},5000);}
function archiveBook(){const selected=archiveItems.filter(e=>!e.locked&&e.status==='approved'&&['story','recipe','memory','memorial','achievement','source'].includes(e.kind));modal('Aile kitabı',`<p>Görmeye yetkili olduğun kişi bilgileri, aile bağları ve arşiv katkıları hazırlanır. Yazdır penceresinde “PDF olarak kaydet” seçebilirsin.</p>${aButton('Kitabı hazırla','book-print','','primary')}`);window.archiveBookEntries=selected;}
async function archiveBookPrint(){const w=window.open('','_blank');if(!w)throw Error('Kitap penceresi engellendi. Bu site için açılır pencereye izin ver.');const html=`<!doctype html><html lang="tr"><meta charset="utf-8"><title>Sarıçiçek Aile Kitabı</title><style>body{font:16px Georgia,serif;line-height:1.7;color:#263e33;max-width:850px;margin:40px auto}h1{font-size:48px}article{break-inside:avoid;border-top:1px solid #ccc;margin-top:30px;padding-top:20px}p{white-space:pre-wrap}img{max-width:100%;max-height:360px;object-fit:contain}small{color:#666}@page{margin:20mm}@media print{button{display:none}}</style><h1>${esc(state.settings.familyTitle)}<br>Aile Kitabı</h1><p>${esc(state.settings.familyStory)}</p><p>Hazırlanma tarihi: ${new Date().toLocaleDateString('tr-TR')}</p><h2>Aile üyeleri ve bağları</h2>${state.people.map(p=>`<article><h3>${esc(p.name)}</h3><small>${esc(p.birthDate||'Doğum tarihi bilinmiyor')}${p.deathDate?' – '+esc(p.deathDate):''}</small><p>${esc(p.biography)}</p><p>${state.relations.filter(r=>r.personA===p.id||r.personB===p.id).map(r=>esc(r.type==='spouse'?'Eşi':r.personA===p.id?'Çocuğu':'Ebeveyni')+': '+esc(state.people.find(x=>x.id===(r.personA===p.id?r.personB:r.personA))?.name||'')).join('<br>')}</p></article>`).join('')}<h2>Arşivimizden</h2>${(window.archiveBookEntries||[]).map(e=>`<article><h3>${esc(e.title)}</h3>${state.photos.find(p=>p.id===e.photoId)?`<img src="${esc(state.photos.find(p=>p.id===e.photoId).url)}" alt="${esc(e.title)}">`:''}<p>${esc(e.body)}</p>${e.kind==='recipe'?`<p>${esc(e.data.ingredients)}</p><p>${esc(e.data.steps)}</p>`:''}<small>${esc(e.author||'')} · ${esc(e.data.date||'')}</small></article>`).join('')}</html>`;w.document.write(html);w.document.close();await Promise.all([...w.document.images].map(im=>im.complete?Promise.resolve():new Promise(resolve=>{im.onload=im.onerror=resolve;setTimeout(resolve,10000);})));w.focus();w.print();}
async function archivePhotoSettings(id){const p=state.photos.find(p=>p.id===id);modal('Fotoğraftakiler ve görünürlük',form(select('Kim görebilir?','visibility',[['family','Aile üyeleri'],['private','Yalnızca yükleyen']],p.visibility||'family')+`<div class="field full"><label>Fotoğraftaki kişiler</label><div class="tags-picker">${state.people.map(x=>`<label class="tag-check"><input name="peopleIds" type="checkbox" value="${esc(x.id)}" ${p.peopleIds?.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div></div>`));submitWith(async(b,f)=>{await archiveApi('/photo-settings','PUT',{photoId:id,visibility:b.visibility,peopleIds:new FormData(f).getAll('peopleIds')});closeModal();await refresh();toast('Etiketler ve görünürlük kaydedildi.');});}
async function archiveMerges(){const r=await archiveApi('/merges');const groups=new Map();for(const p of state.people){const key=p.name.toLocaleLowerCase('tr').replace(/\s+/g,' ').trim();if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);}const duplicates=[...groups.values()].filter(x=>x.length>1);modal('Yinelenen kayıtlar',`<div class="notice">Aynı isim kesin olarak aynı kişi demek değildir. Doğum tarihi ve aile bağlarını kontrol et. Birleştirme ana kaydın biyografisini korur; diğer profil geri alma için arşivlenir.</div>${duplicates.map(g=>`<p>${esc(g[0].name)} · ${g.length} benzer kayıt</p>`).join('')||'<p>Aynı isimle kayıt bulunmadı. Gerekirse farklı yazılan isimleri de seçebilirsin.</p>'}${form(select('Korunacak ana kayıt','targetId',archivePeopleOptions())+select('Ana kayda birleştirilecek kayıt','sourceId',archivePeopleOptions()),'Kayıtları birleştir')}<h3>Birleştirme geçmişi</h3>${r.items.filter(m=>!m.undoneAt).map(m=>`<p>${esc(state.people.find(p=>p.id===m.targetId)?.name||m.targetId)} ${aButton('Geri al','merge-undo',m.id)}</p>`).join('')}`,true);submitWith(async b=>{if(!b.sourceId||!b.targetId||b.sourceId===b.targetId)throw Error('Farklı iki kişi seçin.');await archiveApi('/merges','POST',b);closeModal();await refresh();toast('Kayıtlar birleştirildi.');});}
