function archiveToday(){const today=new Date().toLocaleDateString('en-CA'),week=Date.now()-7*86400000,list=archiveItems.filter(e=>e.kind==='achievement'||Date.parse(e.createdAt)>=week).filter(e=>e.status==='approved').slice(0,6);return`<section class="card ar-section"><div class="section-head"><div><span class="eyebrow">BUGÜN NE OLDU?</span><h2>Ailemizin güzel haberleri</h2></div>${aButton('Bir başarı paylaş','new-kind','achievement')}</div><div class="ar-grid">${list.map(archiveCard).join('')||'<p>Yeni bir mezuniyet, güzel bir haber veya anı paylaş.</p>'}</div><h3 class="ar-section">Bu hafta ailede</h3><p>${state.people.filter(p=>Date.parse(p.createdAt)>=week).length} yeni kişi kaydı · ${state.photos.filter(p=>Date.parse(p.createdAt)>=week).length} fotoğraf · ${archiveItems.filter(e=>Date.parse(e.createdAt)>=week).length} arşiv katkısı</p>${aButton('Tüm katkıları gör','all')}</section>`;}
async function archiveGovernance(){const members=demoMode?[]:(await api('/api/community')).members;const options=[['','Hesap seçin'],[state.user.id,state.user.name],...members.map(m=>[m.id,m.name])];modal('Ailenin devamlılığı',`<section><h3>Çocuk profillerinde veli kontrolü</h3><p>Veli atanan profil, aile bağları, ikameti ve bağlı içerikleri yalnızca veli ve aile yöneticisi görebilir. Diğer üyeler ve moderatörler göremez; özel içeriklerin sahiplik kısıtları ayrıca geçerlidir.</p><form id="ar-guardian-form" class="stack">${select('Kişi','personId',archivePeopleOptions())}${select('Veli hesabı','userId',options)}<button class="btn" type="submit">Veli ata</button><div class="form-error"></div></form><div id="ar-guardians"></div></section><section class="ar-section"><h3>Yönetimi devret</h3><p>Seçtiğin kişi aile yöneticisi olur; sen moderatör olarak devam edersin. İkinci bir moderatör atamak için yönetim panelini kullanabilirsin.</p><form id="ar-transfer-form" class="stack">${select('Yeni yönetici','userId',options.filter(x=>x[0]!==state.user.id))}${input('Onay için YÖNETİMİ DEVRET yaz','confirm','','text','required')}<button class="btn danger" type="submit">Yönetimi devret</button><div class="form-error"></div></form></section>`,true);$('#ar-guardian-form').onsubmit=ev=>{ev.preventDefault();archiveFormTask(ev.currentTarget,async f=>{await archiveApi('/guardians','PUT',Object.fromEntries(new FormData(f)));await archiveGovernance();});};$('#ar-transfer-form').onsubmit=ev=>{ev.preventDefault();archiveFormTask(ev.currentTarget,async f=>{await archiveApi('/transfer','POST',Object.fromEntries(new FormData(f)));closeModal();await refresh();toast('Yönetim devredildi.');});};if(!demoMode){const r=await archiveApi('/guardians');$('#ar-guardians').innerHTML=r.items.map(g=>`<p>${esc(g.name)} · ${esc(g.guardian)} ${aButton('Korumayı kaldır','guardian-remove',g.personId)}</p>`).join('');}}
function archiveBind(){if(archiveMap){archiveMap.remove();archiveMap=null;}if(route==='archive')$('#ar-search').oninput=e=>{archiveQuery=e.target.value;const start=e.target.selectionStart;render();$('#ar-search').focus();$('#ar-search').setSelectionRange(start,start);};if(route==='connections'){$('#ar-kin-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),a=f.get('kinA'),b=f.get('kinB');if(!a||!b){$('#ar-kin-result').textContent='İki kişiyi de seçin.';return;}const path=kinshipPath(state.people,state.relations,a,b);$('#ar-kin-result').innerHTML=path.length?`<h3>${esc(kinshipLabel(path))}</h3><ol class="ar-kin-path">${path.map((x,i)=>`<li><small>${i?esc(x.label):'Başlangıç'}</small><strong>${esc(state.people.find(p=>p.id===x.id)?.name)}</strong></li>`).join('')}</ol>`:'Kayıtlı bağlar arasında bir yol bulunamadı. Eksik aile bağları olabilir.';};$('#ar-year').oninput=e=>{archiveYear=Number(e.target.value);drawArchiveYear();};drawArchiveYear();drawMigrationMap();}if(route==='groups')archiveBindGroups().catch(e=>$('#ar-groups').textContent=e.message);if(route==='profile')$('#main .footer').insertAdjacentHTML('beforebegin',archiveProfileExtras(personId));if(route==='home')$('#main .footer').insertAdjacentHTML('beforebegin',archiveToday());if(route==='history')$('.page-heading')?.insertAdjacentHTML('afterend',aButton('Zaman çizelgesinde gezin','connections'));if(route==='settings'&&isOwner())$('#main .footer').insertAdjacentHTML('beforebegin',`<section class="card ar-section"><h2>Ailenin devamlılığı</h2>${aButton('Veli kontrolü ve yönetim devri','governance')}${aButton('Otomatik yedekler','backups')}</section>`);document.body.classList.toggle('ar-simple',localStorage.getItem('sf-simple')==='1');hydrate();}
async function archiveHandle(action,el){if(!action.startsWith('ar-'))return;const id=el.dataset.id,e=archiveItems.find(x=>x.id===id);switch(action.slice(3)){
 case'new':return archiveNew();case'new-kind':return archiveNew(id);case'edit':return archiveNew(e.kind,e);case'open':return archiveOpen(id);case'tab':archiveTab=id;render();break;case'reload':await archiveLoad();render();break;case'all':archiveTab='all';go('archive');break;case'connections':go('connections');break;case'person':closeModal();go('profile',id);break;case'kin-person':personId=id;go('connections');break;case'profile-achievement':return archiveNew('achievement',{personId:id});case'profile-memorial':return archiveNew('memorial',{personId:id});case'profile-source':return archiveNew('source',{personId:id});
 case'approve':case'reject':await archiveApi('/entries/'+id,'PATCH',{status:action==='ar-approve'?'approved':'rejected'});closeModal();await refresh();break;case'verify':await archiveApi('/entries/'+id,'PATCH',{verify:true});await archiveLoad();return archiveOpen(id);
 case'delete':return confirmAction('Arşiv katkısını kaldır','Bu katkı aile arşivinde görünmeyecek.',async()=>{await archiveApi('/entries/'+id,'DELETE',{});await archiveLoad();});
 case'comment-approve':case'comment-reject':await archiveApi('/comments/'+id,'PATCH',{status:action==='ar-comment-approve'?'approved':'rejected'});toast('Cevap durumu kaydedildi. Kaydı yeniden açınca güncel durum görünür.');break;
 case'record':return archiveRecord(id);case'exhibit':return archiveExhibit(e);case'book':return archiveBook();case'book-print':return archiveBookPrint();case'photo-settings':return archivePhotoSettings(id);case'photo-memory':return archiveNew('memory',{photoId:id});case'photo-question':return archiveNew('question',{photoId:id});case'simple':localStorage.setItem('sf-simple',localStorage.getItem('sf-simple')==='1'?'0':'1');document.body.classList.toggle('ar-simple',localStorage.getItem('sf-simple')==='1');break;
 case'group-new':return archiveGroupNew();case'group':return archiveGroupOpen(id);case'group-leave':await archiveApi('/groups/'+id,'DELETE',{});closeModal();await archiveBindGroups();break;
 case'group-add':{const members=demoMode?[]:(await api('/api/community')).members;modal('Gruba üye ekle',form(select('Üye','userId',members.map(m=>[m.id,m.name]))));submitWith(async b=>{await archiveApi('/groups/'+id+'/members','POST',b);await archiveGroupOpen(id);});break;}
 case'directory-chat':closeModal();go('chat');toast('Sohbet listesinden bu üyeyi seçerek buluşma isteğini yazabilirsin.');break;
 case'poll-event':modal('Buluşmayı kesinleştir',form(select('Buluşma tarihi','date',e.data.options.map(d=>[d,dateText(d)])),'Takvime ekle'));submitWith(async b=>{await archiveApi('/entries/'+id+'/finalize','POST',b);closeModal();await refresh();toast('Buluşma aile takvimine eklendi.');});break;
 case'quiz-generate':{const rows=state.people.filter(p=>p.birthDate).slice(0,5).map(p=>{const y=Number(p.birthDate.slice(0,4));return`${p.name} hangi yıl doğdu? | ${y} | ${y+3} | ${y-2} | 1`;});$('textarea[name=questions]',dialog).value=rows.join('\n');if(!rows.length)toast('Önce doğum tarihi bilinen aile üyelerini ekle.');break;}
 case'merges':return archiveMerges();case'merge-undo':await archiveApi('/merges/'+id+'/undo','POST',{});closeModal();await refresh();toast('Birleştirme geri alındı.');break;case'governance':return archiveGovernance();case'guardian-remove':await archiveApi('/guardians','DELETE',{personId:id});return archiveGovernance();
 }}
window.archiveApp={load:archiveLoad,bind:archiveBind,handle:archiveHandle};
document.addEventListener('DOMContentLoaded',()=>{document.querySelector('#dialog')?.addEventListener('close',()=>{archiveRouteMap?.remove();archiveRouteMap=null;stopArchiveRecording();clearInterval(archiveGroupTimer);});});
async function archiveFactorPrompt(){return new Promise((resolve,reject)=>{modal('İki aşamalı doğrulama',form(input('Doğrulayıcı kodu veya tek kullanımlık kurtarma kodu','code','','text','required autocomplete="one-time-code"'),'Doğrula'));const onClose=()=>reject(Error('Doğrulama tamamlanmadı.'));dialog.addEventListener('close',onClose,{once:true});submitWith(async b=>{const r=await api(b.code.replace(/[ -]/g,'').length>6?'/api/security/recover':'/api/security/verify','POST',b);sessionStorage.setItem('sf-factor',r.token);dialog.removeEventListener('close',onClose);closeModal();resolve();});});}
async function archiveSecurity(){if(demoMode){modal('İki aşamalı doğrulama','<p>Gerçek hesabında doğrulayıcı uygulamayla ikinci bir güvenlik adımı etkinleştirebilirsin. Önizlemede gerçek hesabın değişmez.</p>');return;}const status=await api('/api/security/status');if(status.enabled){modal('İki aşamalı doğrulama etkin',`<p>${status.recoveryRemaining} kullanılmamış kurtarma kodun var.</p><button class="btn" type="button" id="regenerate-recovery">Kurtarma kodlarını yenile</button>`+form(input('Kapatmak için doğrulayıcı kodu','code','','text','required inputmode="numeric" pattern="[0-9]{6}"'),'Doğrulamayı kapat'));$('#regenerate-recovery').onclick=()=>{modal('Kurtarma kodlarını yenile',form(input('Doğrulayıcı uygulamadaki yeni kod','code','','text','required pattern="[0-9]{6}"'),'Yeni kodlar üret'));submitWith(async b=>{const r=await api('/api/security/recovery','POST',b);showRecoveryCodes(r.recoveryCodes);});};submitWith(async b=>{await api('/api/security/disable','POST',b);sessionStorage.removeItem('sf-factor');closeModal();toast('İki aşamalı doğrulama kapatıldı.');});return;}const setup=await api('/api/security/setup','POST',{});modal('İki aşamalı doğrulamayı kur',`<p>Doğrulayıcı uygulamana aşağıdaki kurulum anahtarını ekle. Anahtarı güvenli bir yerde sakla; etkinleştirme sonrası gösterilen tek kullanımlık kurtarma kodlarını da cihazından ayrı, güvenli bir yerde sakla.</p><code class="ar-secret">${esc(setup.secret)}</code>${form(input('Uygulamanın ürettiği 6 haneli kod','code','','text','required inputmode="numeric" pattern="[0-9]{6}"'),'Etkinleştir')}`);submitWith(async b=>{const r=await api('/api/security/enable','POST',b);sessionStorage.setItem('sf-factor',r.token);showRecoveryCodes(r.recoveryCodes);});}
async function archiveBackups(){if(demoMode){modal('Arşiv yedekleri','<p>Canlı sitede aile yöneticisinin günün ilk arşiv ziyaretinde otomatik kayıt yedeği alınır. Burada gerçek sunucu yedekleri gösterilmez.</p>');return;}const r=await archiveApi('/backups');modal('Arşiv yedekleri',`<div class="notice">Yeni yedekler kayıtlarla birlikte fotoğraf, belge, ses ve video dosyalarının ayrı kopyalarını içerir. Geri yüklemeden önce dosya bütünlüğü doğrulanır. Aynı depodaki kopyalar, depo hesabının tamamen kaybına karşı bağımsız yedek değildir. Canlı Sites sürümünde günlük işlem yönetici ziyaretiyle; bağımsız Node sunucusunda ziyaret gerektirmeyen zamanlayıcıyla çalışır.</div>${aButton('Şimdi yedek al','backup-create','','primary')}<div class="ar-section">${r.items.map(x=>`<article class="ar-comment"><strong>${new Date(x.createdAt).toLocaleString('tr-TR')}</strong><p>${x.recordCount} kayıt</p>${aButton('JSON indir','backup-download',x.id)}${aButton('Eksik kayıtları geri ekle','backup-restore',x.id)}</article>`).join('')||'<p>Henüz yedek yok.</p>'}</div>`,true);}
const archiveHandleBase=archiveHandle;
archiveHandle=async function(action,el){const id=el.dataset.id;if(action==='ar-security')return archiveSecurity();if(action==='ar-backups')return archiveBackups();if(action==='ar-backup-create'){await archiveApi('/backups','POST',{});return archiveBackups();}if(action==='ar-backup-download'){const data=await archiveApi('/backups/'+id);download('saricicek-arsiv-yedegi.json',JSON.stringify(data,null,2));return;}if(action==='ar-backup-restore'){modal('Eksik kayıtları geri ekle',`<p>Mevcut kayıtlar ve dosyalar değiştirilmez. Eksik kayıtlar ve yeni tam yedeklerdeki eksik medya dosyaları geri eklenir. İşlem öncesinde kayıt anlık görüntüsü korunur.</p>${form(input('Onay için ARŞİVİ GERİ YÜKLE yaz','confirm','','text','required'),'Eksik kayıtları geri ekle')}`);submitWith(async b=>{await archiveApi('/backups/'+id+'/restore','POST',b);closeModal();await refresh();toast('Yedekteki eksik kayıtlar geri eklendi.');});return;}return archiveHandleBase(action,el);};window.archiveApp.handle=archiveHandle;
async function archivePhotoEnhance(id){const status=demoMode?{available:false}:await archiveApi('/photo-enhance');modal('Eski fotoğrafı iyileştir',`<p>Özgün fotoğraf korunur. Sonuç, yapay zekâyla değiştirildiği belirtilen ayrı bir kopya olarak kaydedilir.</p>${status.available?form(select('İşlem','mode',[['restore','Çizik ve solmaları iyileştir'],['colorize','Siyah beyaz fotoğrafı renklendir']])+'<label class="tag-check full"><input type="checkbox" name="consent" required> Fotoğrafın işlenmek üzere OpenAI hizmetine gönderilmesini kabul ediyorum.</label>','İyileştirmeyi başlat'):'<div class="notice">İyileştirme hizmeti henüz bağlı değil. Sunucuya hizmet anahtarı eklendiğinde bu özellik etkinleşir. Şu anda fotoğrafın hiçbir dış hizmete gönderilmez.</div>'}`);if(status.available)submitWith(async b=>{await archiveApi('/photo-enhance','POST',{photoId:id,mode:b.mode,consent:!!b.consent});closeModal();await refresh();toast('İyileştirilmiş kopya Avlu’ya eklendi.');});}
const archiveHandleSecurity=archiveHandle;archiveHandle=async function(action,el){if(action==='ar-photo-enhance')return archivePhotoEnhance(el.dataset.id);return archiveHandleSecurity(action,el);};window.archiveApp.handle=archiveHandle;
function archiveReadFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Dosya okunamadı.'));r.readAsDataURL(file);});}
function archiveEventAlbum(id){const entries=archiveItems.filter(e=>e.eventId===id&&e.photoId),event=state.events.find(x=>x.id===id);modal(esc(event?.title||'Etkinlik albümü'),`<p>Buluşmamızdan fotoğraflar ve hatıralar.</p>${aButton('Avlu’dan fotoğraf ekle','event-photo',id)}<div class="ar-grid ar-section">${entries.map(archiveCard).join('')||'<p>Bu etkinliğe henüz fotoğraf bağlanmadı. Yeni fotoğrafı önce Avlu’ya yükleyip burada seçebilirsin.</p>'}</div>`,true);}
const archiveHandlePhoto=archiveHandle;archiveHandle=async function(action,el){if(action==='ar-event-album')return archiveEventAlbum(el.dataset.id);if(action==='ar-event-photo')return archiveNew('memory',{eventId:el.dataset.id});if(action==='ar-source-person-edit')return personForm(el.dataset.id);return archiveHandlePhoto(action,el);};window.archiveApp.handle=archiveHandle;

document.addEventListener('DOMContentLoaded',()=>{const baseSearch=searchDialog;searchDialog=function(treeOnly=false){if(treeOnly)return baseSearch(true);modal('Aile arşivinde ara',`<label class="search" style="width:100%"><input id="ar-global-search" aria-label="Arşivde kişi, yer veya yıl ara" placeholder="Örneğin 1990’larda Gaziantep düğün" autofocus></label><div id="ar-global-results" class="ar-section"></div>`);$('#ar-global-search').focus();$('#ar-global-search').oninput=e=>{const terms=archiveSearchTerms(e.target.value),match=text=>terms.length&&terms.every(t=>String(text).toLocaleLowerCase('tr').includes(t));const rows=[...state.people.filter(p=>match([p.name,p.place,p.country,p.biography,p.birthDate].join(' '))).map(p=>({title:p.name,kind:'Kişi',action:'profile',id:p.id})),...state.photos.filter(p=>match([p.title,p.place,p.date,p.description].join(' '))).map(p=>({title:p.title,kind:'Avlu',action:'photo',id:p.id})),...archiveItems.filter(x=>!x.locked&&match([x.title,x.body,JSON.stringify(x.data)].join(' '))).map(x=>({title:x.title,kind:archiveKinds[x.kind][0],action:'ar-open',id:x.id}))];$('#ar-global-results').innerHTML=rows.slice(0,60).map(r=>`<button class="search-result" data-action="${r.action}" data-id="${esc(r.id)}"><span><strong>${esc(r.title)}</strong><small>${esc(r.kind)}</small></span></button>`).join('')||'<p>Eşleşme bulunamadı. Bir isim, şehir veya yıl deneyebilirsin.</p>';};};});
let archiveRouteMap=null;
function archiveRoutePicker(){if(!window.L)return;archiveRouteMap?.remove();archiveRouteMap=L.map('ar-route-picker',{minZoom:2,maxZoom:10}).setView([37,35],4);L.geoJSON(window.FamilyWorld,{style:{color:'#fff',weight:1,fillColor:'#a9b797',fillOpacity:1}}).addTo(archiveRouteMap);archiveRouteMap.attributionControl.addAttribution('Natural Earth');const marks={};const draw=side=>{const lat=Number($('#f-'+side+'Lat').value),lng=Number($('#f-'+side+'Lng').value);if(marks[side])archiveRouteMap.removeLayer(marks[side]);marks[side]=L.circleMarker([lat,lng],{radius:8,color:side==='from'?'#263e33':'#ac8539'}).addTo(archiveRouteMap);};archiveRouteMap.on('click',event=>{const side=$('input[name=mapTarget]:checked',dialog).value;$('#f-'+side+'Lat').value=event.latlng.lat.toFixed(5);$('#f-'+side+'Lng').value=event.latlng.lng.toFixed(5);draw(side);$('#ar-route-pick-status').textContent=(side==='from'?'Çıkış':'Varış')+' noktası seçildi.';if(side==='from')$('input[name=mapTarget][value=to]',dialog).checked=true;});for(const side of ['from','to'])if($('#f-'+side+'Lat').value)draw(side);setTimeout(()=>archiveRouteMap?.invalidateSize(),100);}

function showRecoveryCodes(codes){modal('Kurtarma kodlarını sakla',`<p>Bu kodlar yalnızca şimdi gösterilir. Her kod bir kez kullanılabilir. Yeni kodlar üretildiğinde eski kodlar iptal edilir.</p><div class="recovery-grid">${codes.map(c=>`<code>${esc(c)}</code>`).join('')}</div><button class="btn primary" type="button" id="download-recovery">Kodları indir</button>`);$('#download-recovery').onclick=()=>download('saricicek-kurtarma-kodlari.txt',codes.join('\n'));}
